namespace helmer {

PrimeStats& prime_stats() {
  static PrimeStats s;
  return s;
}

namespace {

// Number of standard monomials in the variables xp for the monomial ideal generated by
// the xp-parts of `leads`. Returns -1 if that quotient is infinite.
long count_standard(const std::vector<std::vector<int>>& leads, const std::vector<int>& xp) {
  const size_t m = xp.size();
  std::vector<std::vector<int>> L;
  for (auto& l : leads) {
    std::vector<int> r(m);
    bool nonzero = false;
    for (size_t j = 0; j < m; ++j) {
      r[j] = l[xp[j]];
      nonzero |= r[j] > 0;
    }
    if (!nonzero) return 0;  // a lead purely in u: extension is the unit ideal
    L.push_back(std::move(r));
  }
  std::vector<int> bound(m, -1);
  for (auto& r : L) {
    int nz = -1, cnt = 0;
    for (size_t j = 0; j < m; ++j)
      if (r[j] > 0) { nz = static_cast<int>(j); cnt++; }
    if (cnt == 1 && (bound[nz] < 0 || r[nz] < bound[nz])) bound[nz] = r[nz];
  }
  for (int b : bound)
    if (b < 0) return -1;
  // enumerate the box
  long count = 0;
  std::vector<int> e(m, 0);
  while (true) {
    bool divisible = false;
    for (auto& r : L) {
      bool d = true;
      for (size_t j = 0; j < m; ++j)
        if (e[j] < r[j]) { d = false; break; }
      if (d) { divisible = true; break; }
    }
    if (!divisible) count++;
    size_t j = 0;
    while (j < m && ++e[j] >= bound[j]) e[j++] = 0;
    if (j == m) break;
  }
  return count;
}

std::unordered_map<std::string, std::vector<Ideal>>& cache() {
  static std::unordered_map<std::string, std::vector<Ideal>> c;
  return c;
}

std::string cache_key(const Ideal& I) {
  return std::to_string(reinterpret_cast<uintptr_t>(I.ring().get())) + "|" + I.key();
}

struct TRing {
  RingPtr RT;
  int T;
  std::vector<int> id;
};

TRing make_tring(const RingPtr& R) {
  std::vector<std::string> names = R->names();
  std::string Tn = "helmer_T";
  while (R->index_of(Tn) >= 0) Tn += "_";
  names.push_back(Tn);
  TRing t{Ring::make(names), R->nvars(), {}};
  for (int i = 0; i < R->nvars(); ++i) t.id.push_back(i);
  return t;
}

// Minimal polynomial (up to k[u]-content) of z modulo I·k(u)[xp], as a polynomial
// in T and u in the ring RT.
Poly min_poly(const Ideal& I, const Poly& z, const TRing& tr, const std::vector<int>& u,
              const std::vector<int>& xp) {
  std::vector<int> perm(xp.begin(), xp.end());
  perm.push_back(tr.T);
  perm.insert(perm.end(), u.begin(), u.end());
  std::vector<Poly> g;
  for (auto& p : I.gens()) g.push_back(p.embed(tr.RT, tr.id));
  g.push_back(Poly::var(tr.RT, tr.T) - z.embed(tr.RT, tr.id));
  GB G = groebner(tr.RT, g, perm, static_cast<int>(xp.size()));
  Poly mu(tr.RT);
  bool any = false;
  for (auto& p : G.polys) {
    bool free = true;
    for (int v : xp)
      if (p.involves(v)) { free = false; break; }
    if (!free) continue;
    mu = any ? gcd(mu, p) : p;
    any = true;
  }
  if (!any || !mu.involves(tr.T))
    throw std::logic_error("helmer: no minimal polynomial (not zero-dimensional over k(u))");
  return mu;
}

// Seidenberg: in characteristic 0, I·k(u)[xp] + (squarefree min polys of each xp
// variable) is the radical of I·k(u)[xp].
Ideal radicalise(const Ideal& I, const TRing& tr, const std::vector<int>& u,
                 const std::vector<int>& xp) {
  const RingPtr& R = I.ring();
  Ideal J = I;
  for (int v : xp) {
    Poly mu = min_poly(I, Poly::var(R, v), tr, u, xp);
    Poly sq = Poly::constant(tr.RT, 1);
    for (auto& [f, e] : factor(mu))
      if (f.involves(tr.T)) sq = sq * f;
    std::vector<Poly> vals;
    for (int i = 0; i < R->nvars(); ++i) vals.push_back(Poly::var(R, i));
    vals.push_back(Poly::var(R, v));
    J = J + sq.substitute(R, vals);
  }
  return Ideal(R, J.gb().polys);
}

std::vector<Ideal> zero_dim_primes(const Ideal& I0, const std::vector<int>& u,
                                   const std::vector<int>& xp) {
  const RingPtr& R = I0.ring();
  const int n = R->nvars();
  TRing tr = make_tring(R);
  Ideal I = I0;
  bool radicalised = false;
  const int max_tries = 24;
  for (int attempt = 0; attempt < max_tries; ++attempt) {
    Poly z(R);
    if (attempt < static_cast<int>(xp.size()) && attempt < 2) {
      z = Poly::var(R, xp[xp.size() - 1 - attempt]);
    } else {
      long bound = attempt < 6 ? 3 : (attempt < 12 ? 50 : 100000);
      for (int v : xp) z = z + Poly::var(R, v).scale_si(random_coeff(bound));
    }
    Poly mu = min_poly(I, z, tr, u, xp);
    std::vector<Poly> vals;
    for (int i = 0; i < n; ++i) vals.push_back(Poly::var(R, i));
    vals.push_back(z);

    std::vector<Ideal> primes;
    bool ok = true;
    for (auto& [f, e] : factor(mu)) {
      if (!f.involves(tr.T)) continue;  // content in k[u]
      Ideal J = I + f.substitute(R, vals);
      BlockData B = block_lc_lcm(J, u);
      long delta = count_standard(B.gb.lead, xp);
      if (delta != f.degree_in(tr.T)) { ok = false; break; }
      Ideal P(R, B.gb.polys);
      if (!B.h.is_constant()) P = saturate(P, B.h);
      P.canonicalise();
      primes.push_back(std::move(P));
    }
    if (ok) return primes;
    prime_stats().z_retries++;
    if (!radicalised) {  // the failure may be non-reducedness rather than a bad z
      I = radicalise(I, tr, u, xp);
      radicalised = true;
      --attempt;
    }
  }
  throw std::runtime_error("helmer: could not find a separating linear form");
}

std::vector<Ideal> mp_rec(const Ideal& I0) {
  prime_stats().calls++;
  if (std::getenv("HELMER_TRACE")) fprintf(stderr, "[mp] %.300s\n", I0.str().c_str());
  Ideal I(I0.ring(), I0.gb().polys);  // work with the reduced basis
  if (I.gb().is_unit()) return {};
  const RingPtr& R = I.ring();
  if (I.is_zero()) return {Ideal(R)};

  auto key = cache_key(I);
  if (auto it = cache().find(key); it != cache().end()) return it->second;

  std::vector<Ideal> result;
  // 1. factorising split
  std::vector<size_t> order(I.gens().size());
  for (size_t i = 0; i < order.size(); ++i) order[i] = i;
  std::sort(order.begin(), order.end(),
            [&](size_t a, size_t b) { return I.gens()[a].nterms() < I.gens()[b].nterms(); });
  for (size_t idx : order) {
    const Poly& g = I.gens()[idx];
    auto fs = factor(g);
    if (fs.size() == 1 && fs[0].second == 1) continue;  // irreducible
    prime_stats().splits++;
    if (fs.size() == 1) {  // pure power: replace by the base
      std::vector<Poly> gens = I.gens();
      gens[idx] = fs[0].first;
      result = mp_rec(Ideal(R, gens));
    } else {
      for (auto& [f, e] : fs) {
        auto sub = mp_rec(I + f);
        result.insert(result.end(), sub.begin(), sub.end());
      }
      result = minimalise(std::move(result));
    }
    cache()[key] = result;
    return result;
  }

  // 2. reduction to dimension zero over k(u)
  std::vector<int> u = I.independent_set();
  std::vector<char> in_u(R->nvars(), 0);
  for (int v : u) in_u[v] = 1;
  std::vector<int> xp;
  for (int v = 0; v < R->nvars(); ++v)
    if (!in_u[v]) xp.push_back(v);
  BlockData B = block_lc_lcm(I, u);
  Ideal Ib(R, B.gb.polys);
  result = zero_dim_primes(Ib, u, xp);

  // 3. the part of V(I) inside V(h)
  if (!B.h.is_constant()) {
    for (auto& [f, e] : factor(B.h)) {
      auto sub = mp_rec(I + f);
      result.insert(result.end(), sub.begin(), sub.end());
    }
  }
  result = minimalise(std::move(result));
  cache()[key] = result;
  return result;
}

}  // namespace

std::vector<Ideal> minimalise(std::vector<Ideal> P) {
  std::vector<Ideal> uniq;
  std::vector<std::string> keys;
  for (auto& p : P) {
    auto k = p.key();
    if (std::find(keys.begin(), keys.end(), k) != keys.end()) continue;
    keys.push_back(k);
    uniq.push_back(p);
  }
  // sort by dimension, largest first, so containment checks are cheap to order
  std::vector<int> dims;
  for (auto& p : uniq) dims.push_back(p.dim());
  std::vector<size_t> ord(uniq.size());
  for (size_t i = 0; i < ord.size(); ++i) ord[i] = i;
  std::stable_sort(ord.begin(), ord.end(), [&](size_t a, size_t b) { return dims[a] > dims[b]; });
  std::vector<Ideal> out;
  for (size_t i : ord) {
    bool redundant = false;
    for (auto& q : out)  // q has dim >= p; p non-minimal iff q ⊆ p
      if (uniq[i].contains(q)) { redundant = true; break; }
    if (!redundant) out.push_back(uniq[i]);
  }
  for (auto& p : out) p.canonicalise();
  return out;
}

std::vector<Ideal> minimal_primes(const Ideal& I) { return mp_rec(I); }

}  // namespace helmer
